'use strict';
const {Game,LEVELS,NAMES}=ForestMatch,$=s=>document.querySelector(s),boardEl=$('#board'),modal=$('#modal');
let save={unlocked:1,stars:{},best:{},sound:false};try{const stored=JSON.parse(localStorage.getItem('forest-friends-v1'));if(stored&&typeof stored==='object')save={...save,...stored,unlocked:Math.min(12,Math.max(1,Number(stored.unlocked)||1)),stars:stored.stars||{},best:stored.best||{}};}catch{}
let game,shown,selected=-1,busy=false,hammerMode=false,hints=[],hintTimer,toastTimer,pointer=null,suppressClickUntil=0,audioContext=null;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function persist(){try{localStorage.setItem('forest-friends-v1',JSON.stringify(save));}catch{}}
function animal(type,cls=''){return `<svg class="${cls}" aria-hidden="true" viewBox="0 0 100 100"><use href="#animal-${type}"/></svg>`;}
function speak(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2700);}
function sound(kind='pop',chain=1){if(!save.sound)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();const now=audioContext.currentTime,notes=kind==='win'?[523,659,784,1046]:kind==='invalid'?[220]:kind==='select'?[440]:[440+chain*75,660+chain*60];notes.forEach((freq,i)=>{const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='sine';osc.frequency.setValueAtTime(freq,now+i*.07);gain.gain.setValueAtTime(0,now+i*.07);gain.gain.linearRampToValueAtTime(.055,now+i*.07+.01);gain.gain.exponentialRampToValueAtTime(.001,now+i*.07+.18);osc.connect(gain);gain.connect(audioContext.destination);osc.start(now+i*.07);osc.stop(now+i*.07+.2);});}catch{}}
function updateSound(){$('#sound').innerHTML=save.sound?'♫':'♫<span class="off-line"></span>';$('#sound').setAttribute('aria-label',save.sound?'关闭音效':'开启音效');$('#sound').title=save.sound?'关闭音效':'开启音效';}
function render(state=game.snapshot(),animation=null){shown=state;const focusIndex=boardEl.contains(document.activeElement)?Number(document.activeElement.dataset.index):-1;const before=Array.from(boardEl.children).map(el=>({id:el.dataset.id,left:el.offsetLeft,top:el.offsetTop}));const oldPositions=new Map(before.map(p=>[p.id,p]));
 boardEl.innerHTML=state.board.map((t,i)=>{const special=t.special,badge={row:'↔',col:'↕',bomb:'✹'}[special];return `<button type="button" class="tile ${state.ice[i]?'iced':''} ${special?'special-'+special:''} ${selected===i?'selected':''} ${hints.includes(i)?'hinted':''}" data-index="${i}" data-id="${t.id}" aria-label="第${(i>>3)+1}行第${i%8+1}列，${special==='rainbow'?'彩虹花':NAMES[t.type]}${special&&special!=='rainbow'?'，'+({row:'横向特效',col:'纵向特效',bomb:'爆炸特效'})[special]:''}${state.ice[i]?'，有冰块':''}" aria-pressed="${selected===i}" tabindex="${selected>=0?(selected===i?0:-1):(i===0?0:-1)}">${special==='rainbow'?'<span class="rainbow-flower">✿</span>':animal(t.type)}${badge?`<span class="special-badge">${badge}</span>`:''}</button>`;}).join('');
 if(animation==='swap'){for(const el of boardEl.children){const old=oldPositions.get(el.dataset.id);if(old&&(old.left!==el.offsetLeft||old.top!==el.offsetTop)){el.style.setProperty('--sx',old.left-el.offsetLeft+'px');el.style.setProperty('--sy',old.top-el.offsetTop+'px');el.classList.add('swap');}}}
 if(animation==='fall'){for(const el of boardEl.children){const old=oldPositions.get(el.dataset.id);if(!old||old.top!==el.offsetTop||old.left!==el.offsetLeft)el.classList.add('falling');}}
 if(focusIndex>=0)boardEl.children[focusIndex]?.focus({preventScroll:true});boardEl.setAttribute('aria-busy',String(busy));$('#map').disabled=busy;$('#restart').disabled=busy;boardEl.classList.toggle('hammer-mode',hammerMode);$('#moves').textContent=state.moves;$('.moves-box').classList.toggle('low',state.moves<=5);$('#score').textContent=state.score.toLocaleString('zh-CN');$('#best-label').textContent='最佳 '+Math.max(save.best[game.level.id]||0,state.score).toLocaleString('zh-CN');$('#score-fill').style.width=Math.min(100,state.score/15000*100)+'%';
 $('#goals').innerHTML=game.level.goals.map(g=>{const n=Math.min(g.count,state.collected[g.type]),done=n>=g.count;return `<div class="goal ${done?'done':''}" aria-label="${NAMES[g.type]}已收集${n}个，目标${g.count}个">${animal(g.type)}<span>${done?'✓':`${n}<small>/${g.count}</small>`}</span></div>`;}).join('')+(game.initialIce?`<div class="goal ${state.ice.some(Boolean)?'':'done'}" aria-label="剩余${state.ice.filter(Boolean).length}块冰"><div class="ice-mini">❄</div><span>${state.ice.some(Boolean)?state.ice.filter(Boolean).length:'✓'}</span></div>`:'');
 $('#shuffle-count').textContent=state.boosters.shuffle;$('#hammer-count').textContent=state.boosters.hammer;$('#shuffle').disabled=busy||state.status!=='playing'||!state.boosters.shuffle;$('#hammer').disabled=busy||state.status!=='playing'||!state.boosters.hammer;$('#hint').disabled=busy||state.status!=='playing';$('#hammer').classList.toggle('active',hammerMode);$('#hammer').setAttribute('aria-pressed',String(hammerMode));$('#instruction').textContent=hammerMode?'点击要敲掉的小伙伴 · 再点小锤可取消':'滑动交换，或依次点击相邻的两个小伙伴';
}
function updateJourney(){$('#journey-number').textContent=String(game.level.id).padStart(2,'0');$('#journey-fill').style.width=save.unlocked/12*100+'%';}
function start(level){game=new Game(level);busy=false;selected=-1;hammerMode=false;hints=[];$('#level-label').textContent='LEVEL '+String(level).padStart(2,'0');$('#level-name').textContent=game.level.name;updateJourney();render();if(modal.open)modal.close();}
function clearHints(){hints=[];clearTimeout(hintTimer);}
function sleep(ms){return new Promise(resolve=>setTimeout(resolve,reduced?Math.min(ms,20):ms));}
function burst(cells){if(reduced)return;const host=$('#particles');for(const i of cells){const tile=boardEl.children[i];if(!tile)continue;for(let n=0;n<3;n++){const p=document.createElement('i');p.className='particle';p.style.setProperty('--x',tile.offsetLeft+tile.offsetWidth/2+9+'px');p.style.setProperty('--y',tile.offsetTop+tile.offsetHeight/2+9+'px');p.style.setProperty('--dx',(Math.random()-.5)*90+'px');p.style.setProperty('--dy',-15-Math.random()*65+'px');p.style.background=['#f4d381','#fef5d3','#afc78c'][n];host.append(p);setTimeout(()=>p.remove(),700);}}}
function combo(chain){const el=$('#board-message');el.innerHTML=(chain===2?'好事成双！':chain===3?'森林连击！':chain===4?'太棒啦！':'惊喜不停！')+`<small>${chain} 连消</small>`;el.classList.remove('show');void el.offsetWidth;el.classList.add('show');}
async function play(frames){if(!frames.length)return;busy=true;selected=-1;hammerMode=false;clearHints();render(shown);for(const frame of frames){if(frame.kind==='swap'){render(frame.state,'swap');await sleep(190);}else if(frame.kind==='invalid'){render(frame.state,'swap');boardEl.classList.add('shaking');sound('invalid');speak('这一步还不能消除，换个方向试试');await sleep(220);boardEl.classList.remove('shaking');}else if(frame.kind==='pop'){render(frame.state);frame.cells.forEach(i=>boardEl.children[i]?.classList.add('popping'));burst(frame.cells);sound('pop',frame.chain);if(frame.chain>=2)combo(frame.chain);await sleep(270);}else if(frame.kind==='fall'){render(frame.state,'fall');await sleep(290);}else if(frame.kind==='shuffle'){render(frame.state);boardEl.classList.add('shuffling');if(frame.auto)speak('暂时没有可消除的组合，已自动免费洗牌');await sleep(400);boardEl.classList.remove('shuffling');}else render(frame.state);}
 busy=false;render();if(game.status!=='playing')finish();}
function move(a,b){if(busy||game.status!=='playing')return;const result=game.attempt(a,b);play(result.frames);}
function selectTile(i){if(busy||game.status!=='playing')return;clearHints();if(hammerMode){play(game.hammer(i));return;}if(selected<0){selected=i;sound('select');render();}else if(selected===i){selected=-1;render();}else if(game.adjacent(selected,i)){move(selected,i);}else{selected=i;sound('select');render();}}
boardEl.addEventListener('click',e=>{if(Date.now()<suppressClickUntil)return;const tile=e.target.closest('.tile');if(tile)selectTile(Number(tile.dataset.index));});
boardEl.addEventListener('pointerdown',e=>{const tile=e.target.closest('.tile');if(!tile||busy||e.button>0)return;pointer={id:e.pointerId,index:Number(tile.dataset.index),x:e.clientX,y:e.clientY};boardEl.setPointerCapture(e.pointerId);});
boardEl.addEventListener('pointerup',e=>{if(!pointer||pointer.id!==e.pointerId)return;const p=pointer;pointer=null;suppressClickUntil=Date.now()+400;const dx=e.clientX-p.x,dy=e.clientY-p.y;if(Math.max(Math.abs(dx),Math.abs(dy))<16){selectTile(p.index);return;}if(hammerMode)return;const r=p.index>>3,c=p.index%8,n=Math.abs(dx)>Math.abs(dy)?(dx>0?(c<7?p.index+1:-1):(c>0?p.index-1:-1)):(dy>0?(r<7?p.index+8:-1):(r>0?p.index-8:-1));if(n>=0)move(p.index,n);});
boardEl.addEventListener('pointercancel',()=>pointer=null);
boardEl.addEventListener('keydown',e=>{const tile=e.target.closest('.tile');if(!tile||busy)return;const i=Number(tile.dataset.index),directions={ArrowUp:-8,ArrowDown:8,ArrowLeft:-1,ArrowRight:1},d=directions[e.key];if(d!==undefined){e.preventDefault();const n=i+d;if(n<0||n>63||!game.adjacent(i,n))return;if(e.shiftKey){move(i,n);return;}const next=boardEl.children[n];tile.tabIndex=-1;next.tabIndex=0;next.focus();}if(e.key==='Escape'){selected=-1;hammerMode=false;clearHints();render();}});
$('#hint').onclick=()=>{if(busy)return;hammerMode=false;selected=-1;hints=game.legalMoves()[0]||[];render();speak('发光的两个小伙伴，可以交换哦');clearTimeout(hintTimer);hintTimer=setTimeout(()=>{hints=[];if(!busy)render();},4500);};
$('#shuffle').onclick=()=>{if(busy)return;speak('叶子飞一飞，灵感就来啦');play(game.useShuffle());};
$('#hammer').onclick=()=>{if(busy)return;hammerMode=!hammerMode;selected=-1;clearHints();render();if(hammerMode)speak('选一格敲掉吧，冰块也能一起破除');};
$('#sound').onclick=()=>{save.sound=!save.sound;persist();updateSound();if(save.sound)sound('select');speak(save.sound?'森林音效已开启':'森林音效已关闭');};
function openModal(html){$('#modal-body').innerHTML=html;if(!modal.open)modal.showModal();}
$('#modal-close').onclick=()=>{if(game.status==='playing')modal.close();else openMap();};modal.addEventListener('cancel',e=>{if(game.status!=='playing'){e.preventDefault();openMap();}});modal.addEventListener('click',e=>{if(e.target===modal&&game.status==='playing')modal.close();});
function openHelp(){openModal(`<div class="modal-eyebrow">A LITTLE FOREST MAGIC</div><h2 class="modal-title">快乐，很简单</h2><p class="modal-copy">在步数用完前，完成上方所有收集目标。</p><div class="help-row"><span>↔</span><div><b>交换相邻的两个小伙伴</b><small>滑动，或依次点击。横竖三个同色即可消除；无效交换不扣步数。</small></div></div><div class="help-row"><span>✦</span><div><b>四连、五连，藏着小惊喜</b><small>四连生成行列特效；T / L 形生成 3×3 爆炸；五连生成彩虹花，与任意动物交换可清除同色。</small></div></div><div class="help-row"><span>✹</span><div><b>让特效碰个头</b><small>两个特效可以直接交换并同时触发。彩虹花配特效，让所有同色动物都释放特效！</small></div></div><div class="help-row"><span>❄</span><div><b>第 4 关起，试着破冰</b><small>消除冰块上的小伙伴即可破冰；小锤也能破冰。道具每关补满，洗牌和小锤不扣步数。</small></div></div><div class="key-tip">电脑也能用键盘：方向键移动焦点，回车选择；Shift + 方向键交换。<br>过关获得 1 星；剩余至少 5 / 11 步可再得 1 / 2 星。进度保存在当前浏览器。</div><button class="primary-button" id="help-ok">知道啦，去消除</button>`);$('#help-ok').onclick=()=>{if(game.status==='playing')modal.close();else openMap();};}
$('#help').onclick=openHelp;$('#more-help').onclick=openHelp;
function openMap(){openModal(`<div class="modal-eyebrow">YOUR FOREST JOURNEY</div><h2 class="modal-title">去森林里走走</h2><p class="modal-copy">十二站风景，一点一点解锁快乐。<br>已获得 ${Object.values(save.stars).reduce((a,b)=>a+Number(b),0)} / 36 颗星星</p><div class="level-grid">${LEVELS.map(l=>`<button class="level-button ${game.level.id===l.id?'current':''}" data-level="${l.id}" ${l.id>save.unlocked?'disabled':''} aria-label="第${l.id}关 ${l.name}${l.id>save.unlocked?'，未解锁':''}"><b>${l.id>save.unlocked?'♧':String(l.id).padStart(2,'0')}</b><small>${l.id>save.unlocked?'待解锁':'★'.repeat(save.stars[l.id]||0)+'☆'.repeat(3-(save.stars[l.id]||0))}</small></button>`).join('')}</div><p class="modal-copy" style="font-size:10px;margin-top:22px">${game.status==='playing'?'选择其他关卡会重新开始该关。':'选择已解锁的关卡，再来一局吧。'}</p>`);document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.level);if(n===game.level.id&&game.status==='playing'){modal.close();return;}if(game.status==='playing'&&(game.moves<game.level.moves||game.boosters.hammer<2||game.boosters.shuffle<2))confirmStart(n);else start(n);});}
$('#map').onclick=openMap;
function confirmStart(level){openModal(`<div class="modal-animal">${animal(0)}</div><h2 class="modal-title">重新出发？</h2><p class="modal-copy">本局的分数和目标进度将清零，<br>已经获得的关卡星星会保留。</p><button class="primary-button" id="confirm-restart">${level===game.level.id?'重新开始这一关':'前往第 '+level+' 关'}</button><button class="secondary-button" id="cancel-restart">继续这局</button>`);$('#confirm-restart').onclick=()=>start(level);$('#cancel-restart').onclick=()=>modal.close();}
$('#restart').onclick=()=>{if(busy)return;confirmStart(game.level.id);};
function finish(){save.best[game.level.id]=Math.max(save.best[game.level.id]||0,game.score);const won=game.status==='won',stars=game.stars();if(won){save.stars[game.level.id]=Math.max(save.stars[game.level.id]||0,stars);save.unlocked=Math.min(12,Math.max(save.unlocked,game.level.id+1));}persist();updateJourney();if(won)sound('win');const last=game.level.id===12;openModal(`<div class="modal-eyebrow">${won?'A LITTLE WIN, A BIG SMILE':'TAKE A BREATH & TRY AGAIN'}</div><div class="modal-animal">${animal(won?0:2)}</div><h2 class="modal-title">${won?(last?'森林因你而闪耀！':'好心情，收集成功！'):'差一点点，再试一次'}</h2>${won?`<div class="result-stars">${'★'.repeat(stars)}<span class="empty">${'★'.repeat(3-stars)}</span></div>`:''}<p class="modal-copy">${won?(last?'十二站风景都见过了，回头再收集更多星星吧。':'小伙伴们都到齐啦，下一片森林等你发现。'):'步数用完啦。试着用四连和五连制造更多惊喜。'}</p><div class="result-details"><span>本局得分<b>${game.score.toLocaleString('zh-CN')}</b></span><span>${won?'剩余步数':'尚未完成'}<b>${won?game.moves:(game.level.goals.reduce((sum,g)=>sum+Math.max(0,g.count-game.collected[g.type]),0)+game.ice.filter(Boolean).length)}</b></span></div><button class="primary-button" id="result-main">${won?(last?'重游森林':'下一关 · '+LEVELS[game.level.id].name):'再来一次'}</button><button class="secondary-button" id="result-secondary">${won?'重玩本关，挑战三星':'看看森林地图'}</button>`);$('#result-main').onclick=()=>won?(last?openMap():start(game.level.id+1)):start(game.level.id);$('#result-secondary').onclick=()=>won?start(game.level.id):openMap();}
const mobileQuery=matchMedia('(max-width:1120px)');function placeTools(){const host=mobileQuery.matches?$('#mobile-tools'):$('.tools-card');if(mobileQuery.matches)host.append($('#tools'));else host.insertBefore($('#tools'),$('.tool-note'));}mobileQuery.addEventListener('change',placeTools);placeTools();updateSound();start(save.unlocked);
